async function processStockMovements() {
  let currentStock = 451;
  const movements = [
    { type: 'ship', units: 62 },
    { type: 'receive', units: 130 },
    { type: 'ship', units: 156 },
    { type: 'receive', units: 167 }
  ];

  console.log(`Initial stock in bin A7: ${currentStock}`);

  for (const movement of movements) {
    console.log(`\n--- Processing ${movement.type} ${movement.units} units ---`);
    console.log(`Stock before movement: ${currentStock}`);

    if (movement.type === 'ship') {
      const result = await tools.ship_order({ stock: currentStock, units: movement.units });
      console.log(`Ship order result: ${JSON.stringify(result)}`);
      currentStock -= movement.units;
      console.log(`Stock after shipment: ${currentStock}`);
    } else if (movement.type === 'receive') {
      const result = await tools.receive_shipment({ stock: currentStock, units: movement.units });
      console.log(`Receive shipment result: ${JSON.stringify(result)}`);
      currentStock += movement.units;
      console.log(`Stock after receipt: ${currentStock}`);
    }
  }

  console.log(`\n--- All movements complete ---`);
  console.log(`Final stock in bin A7: ${currentStock}`);
}

